//! Ruby SDK emitter — OpenSDK IR → generated Ruby SDK code (Rust port of
//! `@xyd-js/opensdk-ruby`, S6+ W7). Emits the GENERATED-code files (gemspec,
//! entrypoint, client, models, per-resource files); the vendored transport
//! runtime + the SDK's own minitest suite are DEFERRED (verbatim constants +
//! example scaffolding — JS stays authoritative), as are napi + the JS shim.
//!
//! Faithful to the framework orchestrator: the `# Code generated by opensdk.
//! DO NOT EDIT.` ownership header is prepended (+ one blank line) to every
//! `.rb` file, and NOT to the `.gemspec` (unknown extension).

mod client;
mod model;
mod naming;
mod plan;
mod project;
mod rbtype;
mod service;
mod writer;

use serde_json::Value;
use std::collections::{BTreeMap, HashMap};

use naming::{pascal_case, ruby_gem_name, screaming_snake_case};

const HEADER: &str = "Code generated by opensdk. DO NOT EDIT.";

struct Resolved {
    pkg: String,
    module_name: String,
    env_var: String,
}

fn resolve_options(spec: &Value) -> Resolved {
    let title = spec
        .get("info")
        .and_then(|i| i.get("title"))
        .and_then(|t| t.as_str())
        .unwrap_or("");
    let pkg = ruby_gem_name(title);
    let module_name = pascal_case(title);
    let env_var = spec
        .get("security")
        .and_then(|s| s.as_array())
        .and_then(|arr| {
            arr.iter().find_map(|s| {
                s.get("envVar")
                    .and_then(|e| e.as_str())
                    .filter(|e| !e.is_empty())
            })
        })
        .map(|e| e.to_string())
        .unwrap_or_else(|| format!("{}_API_KEY", screaming_snake_case(&pkg)));
    Resolved {
        pkg,
        module_name,
        env_var,
    }
}

/// Prepend the ownership header to `.rb` files (+ blank line); `.gemspec` and
/// other unknown extensions are left untouched.
fn with_header(path: &str, content: String) -> String {
    let ext = path.rsplit('/').next().unwrap_or(path);
    let is_rb = ext
        .rsplit_once('.')
        .map(|(_, e)| e == "rb")
        .unwrap_or(false);
    if is_rb {
        format!("# {HEADER}\n\n{content}")
    } else {
        content
    }
}

/// Generate the Ruby SDK's GENERATED-code file map (path → content). The
/// vendored runtime (`lib/<pkg>/transport.rb`) and test files are intentionally
/// NOT emitted here (deferred to JS).
pub fn generate_ruby(spec: &Value) -> BTreeMap<String, String> {
    let opts = resolve_options(spec);
    let types: HashMap<String, Value> = spec
        .get("types")
        .and_then(|t| t.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|t| {
                    t.get("name")
                        .and_then(|n| n.as_str())
                        .map(|n| (n.to_string(), t.clone()))
                })
                .collect()
        })
        .unwrap_or_default();

    let mut files: BTreeMap<String, String> = BTreeMap::new();
    let mut put = |path: String, content: String| {
        let c = with_header(&path, content);
        files.insert(path, c);
    };

    // generateProject
    put(
        format!("{}.gemspec", opts.pkg),
        project::render_gemspec(spec, &opts.pkg),
    );
    put(
        format!("lib/{}.rb", opts.pkg),
        project::render_entrypoint(spec, &opts.pkg),
    );
    // generateClient
    put(
        format!("lib/{}/client.rb", opts.pkg),
        client::render_client_file(spec, &opts.module_name, &opts.env_var),
    );
    // generateTypes
    put(
        format!("lib/{}/models.rb", opts.pkg),
        model::render_models_file(spec, &opts.module_name),
    );
    // generateResources
    if let Some(resources) = spec.get("resources").and_then(|r| r.as_array()) {
        for resource in resources {
            let (path, content) =
                service::render_service_file(resource, &opts.module_name, &opts.pkg, &types);
            put(path, content);
        }
    }

    files
}
